package com.company.platform.inventory.domain;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.UUID;import org.junit.jupiter.api.Test;
class InventoryDomainTest{@Test void availableStockIsReducedByReservation(){Inventory i=Inventory.create(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());i.adjust(new BigDecimal("10"));i.reserve(new BigDecimal("3"));assertEquals(new BigDecimal("7"),i.available());}@Test void cannotReserveMoreThanAvailable(){Inventory i=Inventory.create(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());i.adjust(new BigDecimal("2"));assertThrows(IllegalStateException.class,()->i.reserve(new BigDecimal("3")));}@Test void reservationCannotBeNegative(){assertThrows(IllegalArgumentException.class,()->Inventory.create(null,UUID.randomUUID(),UUID.randomUUID()));}}
